export function OpeningHours({
  title = "{{title}}",
  accent = "{{accent}}",
  style = "{{style}}",
  highlightToday = {{highlightToday}},
  showNote = {{showNote}},
}) {
  const days = [
    ["Monday", "9:00–17:30"],
    ["Tuesday", "9:00–17:30"],
    ["Wednesday", "9:00–17:30"],
    ["Thursday", "9:00–17:30"],
    ["Friday", "9:00–18:00"],
    ["Saturday", "10:00–14:00"],
    ["Sunday", "Closed"],
  ];
  const bordered = style === "table";
  const cellStyle = bordered ? { border: "1px solid #24143022", padding: "8px 10px" } : { borderBottom: "1px solid #24143014", padding: "6px 2px" };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", maxWidth: 320 }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 17, fontWeight: 700 }}>{title}</h3>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
        <caption style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>Weekly opening hours</caption>
        {bordered && (
          <thead>
            <tr><th scope="col" style={cellStyle}>Day</th><th scope="col" style={{ ...cellStyle, textAlign: "right" }}>Hours</th></tr>
          </thead>
        )}
        <tbody>
          {days.map(([day, hours]) => {
            const today = highlightToday && day === "Wednesday";
            return (
              <tr key={day}>
                <th scope="row" style={{ ...cellStyle, textAlign: "left", fontWeight: 600, color: today ? accent : "inherit" }}>{day}</th>
                <td style={{ ...cellStyle, textAlign: "right", color: today ? accent : "inherit", fontWeight: today ? 700 : 400 }}>{hours}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {showNote && <p style={{ margin: "12px 0 0", fontSize: 12, color: "#241430aa" }}>Kitchen closes 30 minutes before close.</p>}
    </div>
  );
}
